const slowTests = {
  'tests/broadband_test.rs': ['test_broadband_single_source_doa_frequency_triples'],
  'tests/noisy_data_test.rs': ['test_single_source_doa_noisy_10db','test_single_source_doa_noisy_5db','test_single_source_doa_noisy_1db'],
  'tests/integration_test.rs': ['test_single_source_doa'],
};
for (const [f, names] of Object.entries(slowTests))
  await edit(f, names.map(n => [`#[test]\nfn ${n}(`, `#[test]\n#[ignore = "slow"]\nfn ${n}(`]));

// hook: drop skip list, rely on #[ignore]
let h = await file('.claude/hooks/run-tests.sh').text();
h = h.replace(/# Skipping:[\s\S]*?entirely\.\n/, `# Skipping:
#   - Slow tests carry #[ignore = "slow"]; plain \`cargo test\` (what this hook
#     runs) skips them. Run them with \`cargo test -- --include-ignored\`.
#   - MUSICRS_SKIP_HOOK_TESTS=1 in the environment Claude Code was started
#     from disables the hook entirely.
`);
h = h.replace(/skip_args=\(\)[\s\S]*?skip_args=\(--exact "\$\{skip_args\[@\]\}"\)\n\n/, '');
h = h.replace('cargo test --quiet -- "${skip_args[@]}"', 'cargo test --quiet');
h = h.replace('(slow tests in $slow_list skipped)', '(slow #[ignore] tests skipped)');
await write('.claude/hooks/run-tests.sh', h);
await $`git rm -q .claude/hooks/slow-tests.txt`;

